			expandArrow.classList.add('widgetFAQ--arrow-collapsed');
			expandArrow.classList.remove('widgetFAQ--arrow-expanded');
			answer.classList.add("hidden");
			element.setAttribute("aria-expanded", "false");
		}
		e.preventDefault();
		e.stopImmediatePropagation();
		e.stopPropagation();
	}
